int afs_dashboard_command_pack(
    uint8_t *dst_p,
    const struct afs_dashboard_command_t *src_p,
    size_t size)
{
    if (size < 3u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 3);

    dst_p[0] |= pack_left_shift_u8(src_p->alive_counter, 0u, 0x0fu);
    dst_p[0] |= pack_left_shift_u8(src_p->command_valid, 4u, 0x10u);
    dst_p[0] |= pack_left_shift_u8(src_p->clear_fault_request, 5u, 0x20u);
    dst_p[0] |= pack_left_shift_u8(src_p->command_reserved_bits6_7, 6u, 0xc0u);
    dst_p[1] |= pack_left_shift_u8(src_p->requested_headlight_power, 0u, 0x01u);
    dst_p[1] |= pack_left_shift_u8(src_p->requested_headlight_mode, 1u, 0x0eu);
    dst_p[1] |= pack_left_shift_u8(src_p->command_reserved_bits12_15, 4u, 0xf0u);
    dst_p[2] |= pack_left_shift_u8(src_p->checksum, 0u, 0xffu);

    return (3);
}

int afs_dashboard_command_unpack(
    struct afs_dashboard_command_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    if (size < 3u) {
        return (-EINVAL);
    }

    dst_p->alive_counter = unpack_right_shift_u8(src_p[0], 0u, 0x0fu);
    dst_p->command_valid = unpack_right_shift_u8(src_p[0], 4u, 0x10u);
    dst_p->clear_fault_request = unpack_right_shift_u8(src_p[0], 5u, 0x20u);
    dst_p->command_reserved_bits6_7 = unpack_right_shift_u8(src_p[0], 6u, 0xc0u);
    dst_p->requested_headlight_power = unpack_right_shift_u8(src_p[1], 0u, 0x01u);
    dst_p->requested_headlight_mode = unpack_right_shift_u8(src_p[1], 1u, 0x0eu);
    dst_p->command_reserved_bits12_15 = unpack_right_shift_u8(src_p[1], 4u, 0xf0u);
    dst_p->checksum = unpack_right_shift_u8(src_p[2], 0u, 0xffu);

    return (0);
}

