int afs_afs_status_pack(
    uint8_t *dst_p,
    const struct afs_afs_status_t *src_p,
    size_t size)
{
    uint8_t left_servo_feedback_deg;
    uint8_t right_servo_feedback_deg;

    if (size < 8u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 8);

    dst_p[0] |= pack_left_shift_u8(src_p->alive_counter, 0u, 0x0fu);
    dst_p[0] |= pack_left_shift_u8(src_p->required_inputs_valid, 4u, 0x10u);
    dst_p[0] |= pack_left_shift_u8(src_p->fault_present, 5u, 0x20u);
    dst_p[0] |= pack_left_shift_u8(src_p->safe_fallback, 6u, 0x40u);
    dst_p[0] |= pack_left_shift_u8(src_p->status_reserved_bit7, 7u, 0x80u);
    dst_p[1] |= pack_left_shift_u8(src_p->executed_mode, 0u, 0x07u);
    dst_p[1] |= pack_left_shift_u8(src_p->status_reserved_bit11, 3u, 0x08u);
    dst_p[1] |= pack_left_shift_u8(src_p->health_state, 4u, 0xf0u);
    dst_p[2] |= pack_left_shift_u8(src_p->steering_stale, 0u, 0x01u);
    dst_p[2] |= pack_left_shift_u8(src_p->speed_stale, 1u, 0x02u);
    dst_p[2] |= pack_left_shift_u8(src_p->object_stale, 2u, 0x04u);
    dst_p[2] |= pack_left_shift_u8(src_p->dashboard_stale, 3u, 0x08u);
    dst_p[2] |= pack_left_shift_u8(src_p->servo_control_lost, 4u, 0x10u);
    dst_p[2] |= pack_left_shift_u8(src_p->servo_mismatch, 5u, 0x20u);
    dst_p[2] |= pack_left_shift_u8(src_p->beam_control_lost, 6u, 0x40u);
    dst_p[2] |= pack_left_shift_u8(src_p->can_decode_fault, 7u, 0x80u);
    left_servo_feedback_deg = (uint8_t)src_p->left_servo_feedback_deg;
    dst_p[3] |= pack_left_shift_u8(left_servo_feedback_deg, 0u, 0xffu);
    right_servo_feedback_deg = (uint8_t)src_p->right_servo_feedback_deg;
    dst_p[4] |= pack_left_shift_u8(right_servo_feedback_deg, 0u, 0xffu);
    dst_p[5] |= pack_left_shift_u16(src_p->applied_dim_sector_mask, 0u, 0xffu);
    dst_p[6] |= pack_right_shift_u16(src_p->applied_dim_sector_mask, 8u, 0xffu);
    dst_p[7] |= pack_left_shift_u8(src_p->checksum, 0u, 0xffu);

    return (8);
}

int afs_afs_status_unpack(
    struct afs_afs_status_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    uint8_t left_servo_feedback_deg;
    uint8_t right_servo_feedback_deg;

    if (size < 8u) {
        return (-EINVAL);
    }

    dst_p->alive_counter = unpack_right_shift_u8(src_p[0], 0u, 0x0fu);
    dst_p->required_inputs_valid = unpack_right_shift_u8(src_p[0], 4u, 0x10u);
    dst_p->fault_present = unpack_right_shift_u8(src_p[0], 5u, 0x20u);
    dst_p->safe_fallback = unpack_right_shift_u8(src_p[0], 6u, 0x40u);
    dst_p->status_reserved_bit7 = unpack_right_shift_u8(src_p[0], 7u, 0x80u);
    dst_p->executed_mode = unpack_right_shift_u8(src_p[1], 0u, 0x07u);
    dst_p->status_reserved_bit11 = unpack_right_shift_u8(src_p[1], 3u, 0x08u);
    dst_p->health_state = unpack_right_shift_u8(src_p[1], 4u, 0xf0u);
    dst_p->steering_stale = unpack_right_shift_u8(src_p[2], 0u, 0x01u);
    dst_p->speed_stale = unpack_right_shift_u8(src_p[2], 1u, 0x02u);
    dst_p->object_stale = unpack_right_shift_u8(src_p[2], 2u, 0x04u);
    dst_p->dashboard_stale = unpack_right_shift_u8(src_p[2], 3u, 0x08u);
    dst_p->servo_control_lost = unpack_right_shift_u8(src_p[2], 4u, 0x10u);
    dst_p->servo_mismatch = unpack_right_shift_u8(src_p[2], 5u, 0x20u);
    dst_p->beam_control_lost = unpack_right_shift_u8(src_p[2], 6u, 0x40u);
    dst_p->can_decode_fault = unpack_right_shift_u8(src_p[2], 7u, 0x80u);
    left_servo_feedback_deg = unpack_right_shift_u8(src_p[3], 0u, 0xffu);
    dst_p->left_servo_feedback_deg = (int8_t)left_servo_feedback_deg;
    right_servo_feedback_deg = unpack_right_shift_u8(src_p[4], 0u, 0xffu);
    dst_p->right_servo_feedback_deg = (int8_t)right_servo_feedback_deg;
    dst_p->applied_dim_sector_mask = unpack_right_shift_u16(src_p[5], 0u, 0xffu);
    dst_p->applied_dim_sector_mask |= unpack_left_shift_u16(src_p[6], 8u, 0xffu);
    dst_p->checksum = unpack_right_shift_u8(src_p[7], 0u, 0xffu);

    return (0);
}

int afs_afs_status_init(struct afs_afs_status_t *msg_p)
{
    if (msg_p == NULL) return -1;

    memset(msg_p, 0, sizeof(struct afs_afs_status_t));

    return 0;
}

